import{z as s,x as o,o as A,c as m,q as r,j as l,D as B,d as e,s as n,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"记忆系统的实现","description":"","frontmatter":{"title":"记忆系统的实现","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/agent-memory-implementation.md","filePath":"llm/agent-memory-implementation.md","lastUpdated":1791063341000}'),p={name:"llm/agent-memory-implementation.md"};function F(d,E,C,g,h,f){const t=o("Mermaid");return A(),m("div",null,[E[2]||(E[2]=r('<h1 id="记忆系统的实现" tabindex="-1">记忆系统的实现 <a class="header-anchor" href="#记忆系统的实现" aria-label="Permalink to &quot;记忆系统的实现&quot;">​</a></h1><div class="epigraph"><p>记忆不是更大的窗口，是一套有写入时机、检索路径和过期策略的存储系统；窗口外的每个事实都要回答「何时进、何时出」。</p><footer>—— 据 Packer 等，MemGPT（2023）；Park 等，Generative Agents，UIST 2023 整理</footer></div><p><a href="/llm/agent-context-strategies">上一课</a>的压缩是有损管道：保住了未决状态，丢掉了细节。细节要有地方可去，且下次要用时取得回来——这是记忆系统。主干已有单点方法课（<a href="/llm/memgpt">MemGPT</a> 的分页、<a href="/llm/mem0-layer">Mem0 记忆层</a> 的两阶段提炼、<a href="/llm/zep-graphiti">Zep / Graphiti 时序知识图谱记忆</a> 的双时间轴）；本课把它们装进同一张工程图纸：分层、写入、检索、过期。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>跨会话需求具体是四类：用户偏好（称呼、口味）、项目事实（架构决定、账号约定）、失败教训（哪种做法上一次错了）、程序性知识（怎么干活的流程）。<span class="marginnote">直觉类比：这四类就是一个靠谱同事该记住的事——记得你叫他「老徐」不叫「徐工」（偏好）、记得这个项目的密码规则（事实）、记得上次这么干砸了（教训）、记得报销流程怎么走（程序）。新同事入职靠带教，代理的「带教」就是记忆系统。</span>实现要过三道决策，每道都有对称的坑。<strong>写入时机</strong>：在线写（模型顺手调一个记忆工具）便宜但噪声大，模型顺手记的会错、会记 trivia；离线提炼（会话结束后批处理归纳）贵但可控，却有时效——提炼完之前下一场会话已经开始。<strong>表示</strong>：自由文本片段检索最省事，但事实更新时新旧两条并存，检索到旧的照错；结构化档案可覆盖，抽取器却成了新的失败点。<strong>检索与注入</strong>：不注入等于没记；全量注入等于把窗口问题原样买回来（回到<a href="/llm/agent-context-strategies">上下文管理策略</a>）。漏掉过期与删除的记忆库是负债：用户改主意、行使删除权时，没有版本与时间戳的系统无从执行。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按距窗口的远近分四层。<strong>工作记忆</strong>：上下文内，上一课的策略管。<strong>情景记忆</strong>：原始轨迹日志，只追加、带时间戳，是其他层的原料。<strong>语义记忆</strong>：从情景提炼的事实与画像，带置信与生效时间；<a href="/llm/amem-agent-memory">A-MEM 代理记忆</a>强调笔记间组织与连边，<a href="/llm/agent-memory-write">记忆写入与检索</a>写写入规则。<strong>程序性记忆</strong>：怎么做事的知识，落成 <a href="/llm/agents-md-spec">AGENTS.md 项目规范</a>与 <a href="/llm/agent-skills">Anthropic Agent Skills</a> 那类文件与技能，按需加载而非全量驻留。检索打分参考 <a href="/llm/generative-agents">Generative Agents</a> 的三项式：近因、重要性、相关性加权；<span class="marginnote">数字实例：给每条候选记忆算一个总分再排序。比如相关性 0.8、重要性 0.3、近因 0.6 的一条，按 \\(1\\times 0.8 + 0.3\\times 0.3 + 1\\times 0.6 = 1.49\\)；另一条相关性 0.6、重要性 0.9、近因 0.1，得分 \\(0.6 + 0.27 + 0.1 = 0.97\\)——前者胜出，被注入窗口。权重就是旋钮：把「近因」的权重调大，代理就更「喜新厌旧」。</span>时序过滤用 <a href="/llm/zep-graphiti">Zep / Graphiti 时序知识图谱记忆</a>的双时间轴——事实的生效时间与写入时间分开记，「用户当时的住址」与「用户现在的住址」才不混。</p>',7)),(A(),l(i,null,{default:B(()=>[n(t,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20SES%5B%22%E4%BC%9A%E8%AF%9D%E8%BF%9B%E8%A1%8C%E4%B8%AD%22%5D%20--%3E%20WM%5B%22%E5%B7%A5%E4%BD%9C%E8%AE%B0%E5%BF%86%EF%BC%9A%E4%B8%8A%E4%B8%8B%E6%96%87%E5%86%85%22%5D%0A%20%20SES%20--%3E%7C%22%E8%BD%A8%E8%BF%B9%E8%90%BD%E7%9B%98%22%7C%20EPI%5B%22%E6%83%85%E6%99%AF%E8%AE%B0%E5%BF%86%EF%BC%9A%E5%8F%AA%E8%BF%BD%E5%8A%A0%E6%97%A5%E5%BF%97%22%5D%0A%20%20EPI%20--%3E%7C%22%E7%A6%BB%E7%BA%BF%E6%8F%90%E7%82%BC%22%7C%20SEM%5B%22%E8%AF%AD%E4%B9%89%E8%AE%B0%E5%BF%86%EF%BC%9A%E4%BA%8B%E5%AE%9E%20%2B%20%E7%BD%AE%E4%BF%A1%20%2B%20%E7%94%9F%E6%95%88%E6%97%B6%E9%97%B4%22%5D%0A%20%20EPI%20--%3E%7C%22%E5%A4%8D%E7%9B%98%E6%8F%90%E7%82%BC%22%7C%20PRO%5B%22%E7%A8%8B%E5%BA%8F%E6%80%A7%E8%AE%B0%E5%BF%86%EF%BC%9A%E8%A7%84%E5%88%99%E4%B8%8E%E6%8A%80%E8%83%BD%22%5D%0A%20%20NEW%5B%22%E6%96%B0%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20RET%5B%22%E6%A3%80%E7%B4%A2%EF%BC%9A%E7%9B%B8%E5%85%B3%E6%80%A7%20%C3%97%20%E8%BF%91%E5%9B%A0%20%C3%97%20%E6%97%B6%E5%BA%8F%E8%BF%87%E6%BB%A4%22%5D%0A%20%20SEM%20--%3E%20RET%0A%20%20PRO%20--%3E%20RET%0A%20%20RET%20--%3E%20INJ%5B%22%E6%8C%89%E9%A2%84%E7%AE%97%E6%B3%A8%E5%85%A5%E7%AA%97%E5%8F%A3%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[e("把记忆读成缓存层：检索注入等于把窗口外包给存储，外包的代价是检索错误的错误不可见——窗口里的错模型看得到，没被检回的遗漏在评测里表现为「忘了」。打分函数决定人格：近因主导的代理像金鱼，旧约定一过期就忘；相关性主导的代理被陈旧事实缠住，需要时序过滤来解。写入比读取更决定质量：在线写靠模型的判断力，离线提炼靠提炼提示的质量，两处的系统性错误都会固化成「代理坚信的错事实」。检索底座可以直接复用检索栈（"),a("a",{href:"/llm/hipporag"},"HippoRAG"),e(" 的海马体式索引是其一），但底座对不对得起记忆任务，要看它对时序与覆盖的处理。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"双时间轴是记忆系统最常被省掉的一列：只记写入时间，「上周学到的」与「上周生效的」混为一谈；只记生效时间，又无法回答「代理当时为何那样做」。故障复盘用的是摄入时间线，决策依据用的是生效时间线。")],-1)),(A(),l(i,null,{default:B(()=>[n(t,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%A3%80%E7%B4%A2%E6%97%B6%E6%9C%89%E5%A4%9A%E6%9D%A1%E5%80%99%E9%80%89%E4%BA%8B%E5%AE%9E%22%5D%20--%3E%20W%7B%22%E6%89%93%E5%88%86%E6%9D%83%E9%87%8D%E6%80%8E%E4%B9%88%E6%94%BE%3F%22%7D%0A%20%20W%20--%3E%7C%22%E8%BF%91%E5%9B%A0%E4%B8%BB%E5%AF%BC%22%7C%20G%5B%22%E9%87%91%E9%B1%BC%E5%9E%8B%EF%BC%9A%E5%8F%AA%E8%AE%B0%E5%BE%97%E6%9C%80%E8%BF%91%E8%AF%B4%E7%9A%84%3Cbr%2F%3E%E6%97%A7%E7%BA%A6%E5%AE%9A%E4%B8%80%E8%BF%87%E6%9C%9F%E5%B0%B1%E5%BF%98%22%5D%0A%20%20W%20--%3E%7C%22%E7%9B%B8%E5%85%B3%E6%80%A7%E4%B8%BB%E5%AF%BC%22%7C%20T%5B%22%E6%81%8B%E6%97%A7%E5%9E%8B%EF%BC%9A%E8%A2%AB%E9%99%88%E6%97%A7%E4%BA%8B%E5%AE%9E%E7%BC%A0%E4%BD%8F%3Cbr%2F%3E%E6%90%AC%E4%BA%86%E5%AE%B6%E8%BF%98%E5%AF%84%E5%88%B0%E6%97%A7%E5%9C%B0%E5%9D%80%22%5D%0A%20%20W%20--%3E%7C%22%E4%B8%89%E9%A1%B9%E5%BC%8F%20%2B%20%E6%97%B6%E5%BA%8F%E8%BF%87%E6%BB%A4%20%2B%20%E7%BD%AE%E4%BF%A1%22%7C%20B%5B%22%E5%B9%B3%E8%A1%A1%E5%9E%8B%EF%BC%9A%E6%96%B0%E4%BA%8B%E5%AE%9E%E8%A6%86%E7%9B%96%E6%97%A7%E4%BA%8B%E5%AE%9E%3Cbr%2F%3E%E6%8C%89%E7%94%9F%E6%95%88%E6%97%B6%E9%97%B4%E8%BF%87%E6%BB%A4%22%5D%0A%20%20G%20--%3E%20R%5B%22%E4%BA%BA%E6%A0%BC%E7%94%B1%E6%89%93%E5%88%86%E5%87%BD%E6%95%B0%E5%86%B3%E5%AE%9A%3Cbr%2F%3E%E4%B8%8D%E6%98%AF%E7%94%B1%E6%A8%A1%E5%9E%8B%E5%86%B3%E5%AE%9A%22%5D%0A%20%20T%20--%3E%20R%0A%20%20B%20--%3E%20R%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程不承诺无限记忆：记忆库越大，检索与提炼的失败面越大，宁小而准。文档型知识走检索（RAG）不走记忆：两者的差别是「全局事实」与「可查文档」，混装会让代理背文档而不是查文档。<span class="marginnote">常见误区：初学者容易以为「窗口够大就不用做记忆系统」。窗口解决的是「装得下」，解决不了「找得到」与「记得新」——100 万 token 里找一句话照样要检索，用户改了住址照样要覆盖旧事实。窗口是桌面大小，记忆系统是档案室的编目规则，两者不是一回事。</span>用户反馈的留存与删除涉合规（<a href="/llm/continual-feedback-privacy">用户反馈的隐私与合规</a>），脱敏在入库前做（<a href="/llm/pii-redact">PII 脱敏</a>）。长视野上记忆是否真的提升任务成功率，要靠<a href="/llm/agent-eval-success-process">评测：任务成功率与过程</a>的跨会话任务说话，不能靠演示。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>四层结构：工作、情景、语义、程序性；每层有各自的写入与失效语义。</li><li>写入时机先于检索调优：在线写有噪声，离线提炼有时滞，错误都会固化。</li><li>检索打分三项式（近因、重要性、相关性）之上要加时序过滤与置信。</li><li>双时间轴（生效与摄入）是过期、删除与复盘的基础。</li><li>检索遗漏不可见：记忆质量必须用跨会话任务评测，不能靠演示。</li><li>出处：据 Packer 等 MemGPT（2023）、Park 等 Generative Agents（UIST 2023）与各家记忆系统的公开口径整理。</li></ul>',4))])}const T=s(p,[["render",F]]);export{c as __pageData,T as default};
